import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({
  baseDirectory: __dirname,
});

const eslintConfig = [
  {
    ignores: [
      ".next/**",
      "node_modules/**",
      "generated/**",
      "playwright-report/**",
      "playwright-report-dbfree/**",
      "test-results/**",
      "public/**",
      // Auto-generated by Next.js itself on every dev/build run — not
      // authored code, and any fix would just be overwritten.
      "next-env.d.ts",
    ],
  },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    // Playwright's fixture API uses a callback literally named `use`
    // (test.extend({ page: async ({ page }, use) => { ...; await use(page); } })),
    // which collides by name with React 19's use() hook. eslint-plugin-react-hooks
    // matches purely on identifier name and has no way to tell these apart, so it
    // flags Playwright's `use` as a misplaced React hook call. This directory is
    // test infrastructure, not React component code, so React's hook rules don't
    // apply to it at all — scoped here, not disabled project-wide.
    files: ["tests/**/*.ts"],
    rules: {
      "react-hooks/rules-of-hooks": "off",
      "react-hooks/exhaustive-deps": "off",
    },
  },
];

export default eslintConfig;
